// === Tab: mySketch ===
var POLYGON = 3;
var SCALE = 16;
var COLS = 6;
var ROWS = 6;
var pps = []

function setup() {
  createCanvas(600, 600);
  for (let i=0; i<COLS; i++) {
    for (let j=0; j<ROWS; j++) {
      pps.push(new PolyParticle(createVector(i*width/(COLS-1), j*height/(ROWS-1)), SCALE));
    }
  }
  background(255);
  colorMode(HSB, 256);
}

function draw() {
  for (let pp of pps) {
  	pp.update();
  	pp.draw();
  }
}

function mouseClicked() {
  for (let pp of pps) {
    pp.randomForce();
  }
}


function PolyParticle(pos, scale) {
  this.eigenPos = pos;
  this.scale = scale;
  this.speed = createVector();
  this.accel = createVector();
  this.angle = 0;
  this.angVel = 0.01;
  this.colorPhase = floor(random(256));
  this.particles = [];
  for (let i=0; i<POLYGON; i++) {
    let relPos = p5.Vector.fromAngle(TWO_PI*i/POLYGON);
    this.particles.push(new Particle(this, relPos));
  }
}
PolyParticle.prototype.update = function() {
  this.speed.add(this.accel);
  this.eigenPos.add(this.speed);
  this.accel.set(0.0, 0.0);
  this.angle += this.angVel;
  for (let part of this.particles) {
    part.accel.add(this.attraction(part.position));
    for (let otherPart of this.particles) {
      let otherPos = p5.Vector.add(part.position, otherPart.position);
      if (otherPos.magSq() > 0.1) part.accel.add(this.repulsion(otherPos));
    }
    part.update();
  }
}
PolyParticle.prototype.draw = function() {
  fill((frameCount+this.colorPhase)%256, 255, 255);
  noStroke(); //stroke(random(255));
  push();
  translate(this.eigenPos.x, this.eigenPos.y);
  rotate(this.angle);
  scale(this.scale);
  beginShape();
  for (let part of this.particles) {
    vertex(part.position.x, part.position.y);
  }
  endShape(CLOSE);
  pop();
}
PolyParticle.prototype.repulsion = function(relPos) {
  let mag = relPos.mag();
  let f = 0.001 / relPos.magSq();               
  return createVector(f*relPos.x/mag, f*relPos.y/mag);
}
PolyParticle.prototype.attraction = function(relPos) {
  var mag = relPos.mag();
  var f = -0.00001 * relPos.magSq();               
  return createVector(f*relPos.x/mag, f*relPos.y/mag);
}
PolyParticle.prototype.randomForce = function() {
  for (let part of this.particles) {
    part.accel.add(p5.Vector.random2D().mult(this.scale/1000));
  }
}


function Particle(parent, position) {
  this.parent = parent;
  this.position = position;
  this.speed = createVector(0.0, 0.0);
  this.accel = createVector(0.0, 0.0);
}
Particle.prototype.update = function() {
    this.speed.add(this.accel);
    this.position.add(this.speed);
    this.accel.set(0.0, 0.0);
}

